      "description": "Derived via slugify() (ticketd/app/util.py:4-6). NOT guaranteed unique — see PB-003/OQ-001."
    },
    "priority": {
      "type": "string",
      "description": "Stored value is always low/med/high after app-layer coercion on create, but no re-validation happens on read -- schema reflects the DB CHECK constraint, not a stronger app-level guarantee."
    },
    "status": { "type": "string", "enum": ["open", "closed"] },
    "assignee_id": {
      "type": ["integer", "null"],
      "description": "Dead field -- no route ever sets this. See docs/domain/users.md."
    },
