      "type": "string",
      "description": "datetime.now().isoformat() -- naive local time, no timezone offset. See PB-010/OQ-006."
    },
    "closed_at": {
      "type": ["string", "null"],
      "description": "Same naive-local-time construction; null until closed."
    }
  }
}

